using MediatR;using Microsoft.AspNetCore.Mvc;using WhatsBiz.Api.Authorization;using WhatsBiz.Application.Features.Purchases;using WhatsBiz.SharedKernel;
namespace WhatsBiz.Api.Controllers;
[ApiController,Route("api/purchases")]public sealed class PurchasesController(ISender sender):ControllerBase{[HttpGet,HasPermission(Permissions.Purchase.View)]public Task<PagedPurchases> List([FromQuery]string? search,[FromQuery]string? status,[FromQuery]Guid? supplierId,[FromQuery]DateTimeOffset? from,[FromQuery]DateTimeOffset? to,[FromQuery]int pageNumber=1,[FromQuery]int pageSize=20,CancellationToken token=default)=>sender.Send(new GetPurchases(search,status,supplierId,from,to,pageNumber,pageSize),token);[HttpGet("{id:guid}"),HasPermission(Permissions.Purchase.View)]public Task<PurchaseDto> Get(Guid id,CancellationToken token)=>sender.Send(new GetPurchase(id),token);[HttpPost,HasPermission(Permissions.Purchase.Create)]public Task<PostedPurchaseDto> Create(PurchaseInput input,CancellationToken token)=>sender.Send(new CreatePurchase(input),token);[HttpPut("{id:guid}"),HasPermission(Permissions.Purchase.Edit)]public Task<PurchaseDto> Update(Guid id,PurchaseInput input,CancellationToken token)=>sender.Send(new UpdatePurchase(id,input),token);[HttpDelete("{id:guid}"),HasPermission(Permissions.Purchase.Delete)]public async Task<IActionResult> Delete(Guid id,CancellationToken token){await sender.Send(new DeletePurchase(id),token);return NoContent();}[HttpPost("payment"),HasPermission(Permissions.Purchase.Payment)]public async Task<IActionResult> Payment(AddPurchasePaymentInput input,CancellationToken token){await sender.Send(new AddPurchasePayment(input),token);return Ok();}[HttpPost("return"),HasPermission(Permissions.Purchase.Return)]public async Task<IActionResult> Return(PurchaseReturnInput input,CancellationToken token){await sender.Send(new ReturnPurchase(input),token);return Ok();}[HttpGet("today"),HasPermission(Permissions.Purchase.View)]public Task<PurchaseDashboardDto> Today(CancellationToken token)=>sender.Send(new GetPurchaseDashboard(),token);[HttpGet("export"),HasPermission(Permissions.Purchase.View)]public async Task<IActionResult> Export(CancellationToken token)=>File(await sender.Send(new ExportPurchases(),token),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","purchases.xlsx");[HttpGet("template"),HasPermission(Permissions.Purchase.Create)]public async Task<IActionResult> Template(CancellationToken token)=>File(await sender.Send(new PurchaseTemplate(),token),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","purchase-import-template.xlsx");}
